using System;using System.IO;using System.Reflection;using Newtonsoft.Json.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using SpatialWallpaper.Content;
public static class ManagerUiRenderChecks {
 public static void Run(){try{EditorSceneManager.OpenScene("Assets/Generated/Manager.unity");var view=UnityEngine.Object.FindObjectOfType<ContentLibraryView>();var type=typeof(ContentLibraryView);type.GetField("ui",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(view,new CalibrationWidgets(view.Font));type.GetMethod("Build",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(view,null);var state=JObject.Parse(File.ReadAllText(Environment.GetEnvironmentVariable("SDK_UI_STATE")));type.GetMethod("Render",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(view,new object[]{state});File.WriteAllText(Environment.GetEnvironmentVariable("SDK_UI_RESULT"),"passed-render-replay");EditorApplication.Exit(0);}catch(Exception error){File.WriteAllText(Environment.GetEnvironmentVariable("SDK_UI_RESULT"),error.ToString());Debug.LogException(error);EditorApplication.Exit(1);}}
}
